"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useRef } from "react";
import type { ComponentProps } from "react";

export type NumberTickerPrimitiveProps = Omit<ComponentProps<typeof motion.span>, "children"> & {
  value: number;
  format?: (value: number) => string;
};

const visuallyHidden = { position: "absolute", width: 1, height: 1, padding: 0, margin: -1, overflow: "hidden", clip: "rect(0, 0, 0, 0)", whiteSpace: "nowrap", border: 0 } as const;

export function NumberTickerPrimitive({ value, format = (number) => number.toLocaleString(), ...props }: NumberTickerPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  const previous = useRef(value);
  const direction = value >= previous.current ? 1 : -1;
  const label = format(value);
  useEffect(() => { previous.current = value; }, [value]);

  return (
    <motion.span {...props} style={{ ...props.style, display: "inline-grid", overflow: "hidden" }}>
      <span aria-live="polite" style={visuallyHidden}>{label}</span>
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={value}
          aria-hidden="true"
          initial={reduceMotion ? false : { y: direction * 24, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={reduceMotion ? { opacity: 0 } : { y: direction * -24, opacity: 0 }}
          transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, ease: [0.16, 1, 0.3, 1] }}
          style={{ gridArea: "1 / 1" }}
        >
          {label}
        </motion.span>
      </AnimatePresence>
    </motion.span>
  );
}
